#include <iostream>
using namespace std;

int main() {
    long long n;
    cin >> n;
    const long long MOD = 1000000007;

    long long base1 = 27; // 3^3
    long long base2 = 7;

    long long pow1 = 1, pow2 = 1;
    long long a = base1 % MOD;
    long long b = base2 % MOD;
    long long e = n;

    // fast exponentiation for base1^n
    while (e > 0) {
        if (e & 1) pow1 = (pow1 * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }

    e = n;
    // fast exponentiation for base2^n
    while (e > 0) {
        if (e & 1) pow2 = (pow2 * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }

    long long result = (pow1 - pow2) % MOD;
    if (result < 0) result += MOD;

    cout << result << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    long long n;
    cin >> n;
    const long long MOD = 1000000007;
    long long a = 27 % MOD;
    long long b = 7 % MOD;

    auto mod_pow = [&](long long base, long long exp) {
        long long result = 1;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    };

    long long x = mod_pow(a, n);
    long long y = mod_pow(b, n);
    long long ans = (x - y) % MOD;
    if (ans < 0) ans += MOD;
    cout << ans << endl;
    return 0;
}

